llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "In humans, ingestion of 23.6 mg lycopene in tomato paste yielded only 0.17% systemic availability, showing that a large, highly lipophilic isoprenoid can be very poorly absorbed; this is affirmative low-F evidence despite low assay-transfer weight.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Capsule dosing of 38 mg lycopene gave only ~2.6% systemic availability in humans, another direct low-F result for a structurally related polyisoprenoid lipid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "A deuterated lycopene tracer study estimated only 1.2% newly absorbed lycopene in humans, supporting low systemic availability for large isoprenoid lipids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Synthetic lycopene dispersed in oil gave about 1.2% systemic availability in humans, reinforcing that even lipid-dispersed large isoprenoids can have very low oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "A 13C-lycopene study estimated 24.5% bioavailability for cis-lycopene, which is above the 20% threshold and is a structurally relevant contradictory observation; however, it is an outlier relative to most lycopene systemic-availability measurements.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Phytoene, a smaller C40 isoprenoid, showed 58.5% estimated absorption in humans, providing structurally relevant contradictory evidence that some highly lipophilic isoprenoids can be well absorbed.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Hyperforin, a prenylated lipophilic natural product, showed high oral bioavailability in volunteers, another contradictory example; but its lower molecular weight and ionizable enol differ from the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "Finerenone showed 43.5% absolute bioavailability in humans, but as a small, moderately lipophilic drug it has limited chemical transferability to a 863 Da polyprenyl quinone.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted low (F < 20%) because the query is an extremely lipophilic 863 Da polyprenyl quinone; the most chemically relevant human data for large isoprenoid lipids (lycopene) predominantly show low systemic availability, and the severe physicochemical liabilities support poor absorption. High-F examples from smaller or less lipophilic molecules, and from phytoene, are not sufficient to overcome this.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability data for CoQ10/ubiquinone itself were provided.",
    "Lycopene bioavailability estimates vary widely by formulation, food matrix, and tracer methodology, creating conflicting structural analogies.",
    "Transfer scores for the structurally similar carotenoid evidence are low, limiting its weight.",
    "No data address bile-salt-dependent absorption, formulation, or food effects for the query molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

